const FAM_SILUETA={"Jotes, Aguiluchos y afines":"rapaz","Lechuzas":"rapaz","Halcones y Caranchos":"rapaz","Burgos":"rapaz","Chajaes":"garza","Carau":"garza","Flamencos":"garza","Macaes":"garza","Cigüeñas":"garza","Cormoranes y Anhingas":"garza","Garzas, Bandurrias y afines":"garza","Pelícanos":"garza","Anátidos":"pato","Rálidos, Gallinetas y afines":"pato","Palomas y Tortolitas":"paloma","Loros, Cotorras y afines":"loro","Cacatúas":"loro","Aves Playeras":"playero","Escúas":"playero","Gaviotas, Gaviotines y Rayadores":"playero","Picaflores":"picaflor"};
// Las siluetas se declaran una sola vez como reglas CSS (con 1.088 tarjetas, repetir el SVG en cada una hacía lento el álbum)
(function(){const st=document.createElement('style');st.textContent=Object.keys(SILUETAS).map(k=>`.sil-${k}{background-image:url("${SILUETAS[k]}")}`).join('');document.head.appendChild(st);})();
function getSilueta(f){const k=SILUETAS[FAM_SILUETA[f]]?FAM_SILUETA[f]&&FAM_SILUETA[f]:'pajarito';return `<div class="fig-silueta"><span class="sil-i sil-${k}" role="img" aria-label="silueta"></span></div>`;}

let campoIdx=0;
function campoNav(dir){campoIdx=(campoIdx+dir+3)%3;campoGo(campoIdx);}
function initCarrusel(){
  const wrap=document.getElementById('campo-carrusel');
  const slides=document.querySelectorAll('#campo-track .carrusel-slide');
  if(wrap&&slides.length){
    const w=wrap.offsetWidth;
    slides.forEach(s=>s.style.width=w+'px');
  }
}
function campoGo(idx){
  campoIdx=idx;
  const wrap=document.getElementById('campo-carrusel');
  const t=document.getElementById('campo-track');
  if(t&&wrap){
    const w=wrap.offsetWidth;
    document.querySelectorAll('#campo-track .carrusel-slide').forEach(s=>s.style.width=w+'px');
    t.style.transform=`translateX(-${idx*w}px)`;
  }
  document.querySelectorAll('.carrusel-dot').forEach((d,i)=>d.classList.toggle('active',i===idx));
}
(function(){
  let sx=0;
  document.addEventListener('DOMContentLoaded',()=>{
    const w=document.getElementById('campo-carrusel');
    if(!w)return;
    initCarrusel();window.addEventListener('resize',()=>campoGo(campoIdx));
    w.addEventListener('touchstart',e=>sx=e.touches[0].clientX,{passive:true});
    w.addEventListener('touchend',e=>{const d=sx-e.changedTouches[0].clientX;if(Math.abs(d)>40)campoNav(d>0?1:-1);},{passive:true});
  });
})();

function irAlbum(filtroVal){
  if(aOtra('album','irAlbum',[filtroVal])) return;
  const bts=document.querySelectorAll('.fb');
  bts.forEach(b=>b.classList.remove('active'));
  if(filtroVal==='enc'){filtro='enc';bts.forEach(b=>{if(b.textContent.includes('Encontradas'))b.classList.add('active');});}
  else{filtro='todas';bts.forEach(b=>{if(b.textContent.includes('Todas'))b.classList.add('active');});}
  famFiltro='';lugFiltro='';actualizarFiltrosUI();
  renderAlbum();
}


