let LUGARES_MAP = [];   // se carga desde avistamientos.json (ver cargarDatos)
let mapaAvesOrdenadas = [];
let modalNavDir = 1;

// (el mapa vive más abajo: sección MAPA con Leaflet)


// Carga avistamientos.json (lo genera sync/sync_ebird.py desde el CSV de eBird)
async function cargarDatos() {
  try {
    const res = await fetch('/avistamientos.json?v=' + Date.now());
    const d = await res.json();
    AVIST_INITIAL = d.avistamientos || {};
    Object.values(AVIST_INITIAL).forEach(a => { if(a.foto && a.foto[0] !== '/' && !/^https?:/.test(a.foto)) a.foto = '/' + a.foto; });
    LUGARES_MAP = d.lugares || [];
  } catch(e) {
    console.error('No se pudo cargar avistamientos.json', e);
  }
}
function escHtml(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
// ── MAPA (Leaflet + OpenStreetMap; se carga solo al abrir la pestaña Mapa) ──
let mapa = null, mapaP = null, _lfP = null, mapaMarkers = [], mapaGrupo = null;
const MAPA_CBA = [[-35.0, -65.8], [-29.5, -61.8]], MAPA_ARG = [[-55.2, -73.6], [-21.7, -53.5]];
function cargarLeaflet() {
  if(window.L) return Promise.resolve();
  if(_lfP) return _lfP;
  _lfP = new Promise((ok, err) => {
    const l = document.createElement('link');
    l.rel = 'stylesheet'; l.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
    l.integrity = 'sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY='; l.crossOrigin = '';
    document.head.appendChild(l);
    const sc = document.createElement('script');
    sc.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
    sc.integrity = 'sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo='; sc.crossOrigin = '';
    sc.onerror = () => { _lfP = null; err(); };
    sc.onload = () => {
      const mc = document.createElement('link');
      mc.rel = 'stylesheet'; mc.href = 'https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.css';
      mc.integrity = 'sha256-YU3qCpj/P06tdPBJGPax0bm6Q1wltfwjsho5TR4+TYc='; mc.crossOrigin = '';
      document.head.appendChild(mc);
      const sm = document.createElement('script');
      sm.src = 'https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js';
      sm.integrity = 'sha256-Hk4dIpcqOSb0hZjgyvFOP+cEmDXUKKNE/tT542ZbNQg='; sm.crossOrigin = '';
      sm.onload = ok; sm.onerror = () => { _lfP = null; err(); };
      document.head.appendChild(sm);
    };
    document.head.appendChild(sc);
  });
  return _lfP;
}
function initLeafletMap() {
  const box = document.getElementById('mapa-leaflet'); if(!box) return Promise.resolve();
  if(mapaP) { if(mapa) setTimeout(() => mapa.invalidateSize(), 50); return mapaP; }
  mapaP = cargarLeaflet().then(construirMapa).catch(() => { mapaP = null; box.innerHTML = '<div class="mapa-error">No se pudo cargar el mapa. Revisá tu conexión y volvé a entrar.</div>'; });
  return mapaP;
}
function construirMapa() {
  const box = document.getElementById('mapa-leaflet'); box.innerHTML = '';
  mapa = L.map(box, {minZoom: 3, maxZoom: 18, zoomSnap: .5});
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {maxZoom: 19, attribution: '© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(mapa);
  const max = Math.max(1, ...LUGARES_MAP.map(l => l.count));
  // Los lugares cercanos se agrupan según el zoom (círculo crema = grupo de lugares) y se abren al acercarse
  mapaGrupo = L.markerClusterGroup({
    maxClusterRadius: 46, showCoverageOnHover: false, spiderfyOnMaxZoom: true, disableClusteringAtZoom: 14,
    iconCreateFunction: c => {
      const hijos = c.getAllChildMarkers(), n = hijos.length, esp = new Set();
      hijos.forEach(h => h.options.ids.forEach(id => esp.add(id)));
      const sz = Math.round(Math.max(34, 26 + 22 * Math.sqrt(esp.size / max)));
      return L.divIcon({className: 'mk-wrap', html: `<div class="mk mk-g" style="width:${sz}px;height:${sz}px" title="${n} lugares · ${esp.size} especies distintas">${esp.size}</div>`, iconSize: [sz, sz]});
    }
  });
  mapaMarkers = LUGARES_MAP.map((l, i) => {
    const sz = Math.round(26 + 22 * Math.sqrt(l.count / max));
    const ic = L.divIcon({className: 'mk-wrap', html: `<div class="mk" style="width:${sz}px;height:${sz}px">${l.count}</div>`, iconSize: [sz, sz], iconAnchor: [sz / 2, sz / 2], popupAnchor: [0, -sz / 2]});
    const m = L.marker([l.lat, l.lon], {icon: ic, title: l.nombre, riseOnHover: true, ids: l.ids});
    mapaGrupo.addLayer(m);
    m.bindPopup(() => mapaPopup(i), {className: 'mk-pop', maxWidth: 300, autoPanPaddingTopLeft: [16, 20], autoPanPaddingBottomRight: [16, 16]});
    m.on('popupopen', () => { const e = m.getElement(); if(e) e.querySelector('.mk').classList.add('on'); });
    m.on('popupclose', () => { const e = m.getElement(); if(e) e.querySelector('.mk').classList.remove('on'); });
    return m;
  });
  mapa.addLayer(mapaGrupo);
  mapaVer('todos');
}
function mapaVer(modo) {
  document.querySelectorAll('.mreg-b').forEach(b => b.classList.toggle('on', b.dataset.v === modo));
  if(!mapa) return;
  mapa.invalidateSize();
  if(modo === 'arg') mapa.fitBounds(MAPA_ARG);
  else if(modo === 'cba') mapa.fitBounds(MAPA_CBA);
  else if(LUGARES_MAP.length) mapa.fitBounds(L.latLngBounds(LUGARES_MAP.map(l => [l.lat, l.lon])), {padding: [40, 40], maxZoom: 12});
  else mapa.fitBounds(MAPA_ARG);
}
function mapaPopup(i) {
  const l = LUGARES_MAP[i];
  const lista = l.ids.filter(id => avist[id]).map(id => AVES.find(a => a.id === id)).filter(Boolean).sort((a, b) => a.comun.localeCompare(b.comun, 'es'));
  const el = document.createElement('div'); el.className = 'mk-body';
  el.innerHTML = `<div class="mk-tit">${escHtml(l.nombre)}</div><div class="mk-sub">${lista.length} especie${lista.length === 1 ? '' : 's'}${l.prov && PROV[l.prov] ? ' · ' + escHtml(PROV[l.prov]) : ''}</div>
    <div class="mk-lista">${lista.map(a => `<button class="mk-sp" data-id="${a.id}">${escHtml(a.comun)}</button>`).join('')}</div>
    <button class="mk-alb">Ver en el álbum →</button>`;
  el.addEventListener('click', e => {
    const b = e.target.closest('.mk-sp');
    if(b) { mapaAvesOrdenadas = lista.slice(); openM(+b.dataset.id); }
    else if(e.target.closest('.mk-alb')) mapaAlbum(i);
  });
  return el;
}
function mapaAlbum(i) {
  if(aOtra('album','mapaAlbum',[i])) return;
  const l = LUGARES_MAP[i];
  if(l.prov && l.prov !== 'X' && REGION === 'cba') setRegion('arg');
  irAlbum('enc'); lugFiltro = String(i); actualizarFiltrosUI(); renderAlbum();
}



