function slugAve(comun) {
  return 'ave-' + comun.toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9]+/g,'-')
    .replace(/^-|-$/g,'');
}
function openM(id) {
  curId=id;
  const ave=AVES.find(a=>a.id===id);
  const av=avist[id];
  // URL solo para aves encontradas
  if(av) { try{ history.replaceState(null,'',location.pathname+location.search+'#'+slugAve(ave.comun)); }catch(e){} document.title = ave.comun+' · Félix Santiago Aves'; }
  const mNombre = document.getElementById('m-nombre');
  const mComun = document.getElementById('m-comun');
  const slideClass = modalNavDir >= 0 ? 'modal-slide-right' : 'modal-slide-left';
  mNombre.classList.remove('modal-slide-right','modal-slide-left');
  mComun.classList.remove('modal-slide-right','modal-slide-left');
  void mNombre.offsetWidth; // reflow para reiniciar animación
  mNombre.textContent=ave.nombre; mNombre.classList.add(slideClass);
  mComun.textContent=ave.comun+' · '+ave.familiaEsp; mComun.classList.add(slideClass);

  // Ficha
  const ficha=FICHAS[ave.nombre];
  const fichaEl=document.getElementById('m-ficha');
  if(fichaEl){
    if(ficha){
      const estadoClass=ficha.estado.toLowerCase().includes('migrat')?'migratorio':ficha.estado.toLowerCase().includes('introducida')?'introducida':'residente';
      fichaEl.innerHTML=`
        <div class="ficha-row"><span class="ficha-label">Nombre común</span><span class="ficha-val">${ave.comun}</span></div>
        <div class="ficha-row"><span class="ficha-label">Nombre científico</span><span class="ficha-cientifico">${ave.nombre}</span></div>
        <div class="ficha-row"><span class="ficha-label">Grupo</span><span class="ficha-val">${ave.familiaEsp}</span></div>
        <div class="ficha-row ficha-col"><span class="ficha-label">Característica</span><span class="ficha-val ficha-car">${ficha.estado}</span></div>
        ${ficha.curiosidad?`<div class="ficha-row ficha-col"><span class="ficha-label">Dato curioso</span><span class="ficha-val ficha-dato">${ficha.curiosidad}</span></div>`:''}`;
      fichaEl.style.display='block';
    } else { fichaEl.style.display='none'; }
  }

  // Foto
  const img=document.getElementById('m-img'), ph=document.getElementById('m-ph');
  const mPrev=document.getElementById('m-prev');
  if(av&&av.foto){
    img.src=av.foto; img.alt=ave.comun+' ('+ave.nombre+') - '+ave.familiaEsp+' - Argentina'; img.style.display='block'; ph.style.display='none';
    mPrev.style.backgroundImage='none';
    mPrev.style.filter='none';
  } else {
    img.style.display='none'; ph.style.display='none';
    const sil=SILUETAS[FAM_SILUETA[ave.familiaEsp]||'pajarito']||SILUETAS['pajarito'];
    mPrev.style.backgroundImage=`url("${sil}")`;
    mPrev.style.backgroundSize='contain';
    mPrev.style.backgroundRepeat='no-repeat';
    mPrev.style.backgroundPosition='center center';
    mPrev.style.filter='brightness(0.5)';
  }

  // Info avistamiento
  const encInfo=document.getElementById('m-enc-info');
  const avistEl=document.getElementById('m-avist');
  if(encInfo){
    if(av){
      encInfo.style.display='block';
      if(avistEl) avistEl.innerHTML=`<p>📅 <strong>Primer registro:</strong> ${fmtFecha(av.fecha)}</p>${av.lugar?`<p>📍 <strong>Lugar:</strong> ${av.lugar}${av.prov&&av.prov.length?' · '+av.prov.map(p=>PROV[p]||p).join(', '):''}</p>`:''} ${av.notas?`<p>📝 <strong>Notas:</strong> ${av.notas}</p>`:''}`;
    } else {
      encInfo.style.display='none';
      const pendEl=document.getElementById('m-pending-info');
      const pendDetail=document.getElementById('m-pending-detail');
      if(pendEl) pendEl.style.display='block';
      if(pendDetail) pendDetail.innerHTML=`<span style="font-style:italic;color:var(--ti)">Todavía no la encontré — la tengo en la mira y la sigo buscando.</span>`;
    }
  }
  const pendReset=document.getElementById('m-pending-info');
  if(av && pendReset) pendReset.style.display='none';

  pintarLink(ave);
  document.getElementById('modal-ov').classList.add('open');
  updateModalArrows();
}


