// ── LIGHTBOX ──────────────────────────────────────────────────────────────────
let GALERIA = [];
let lbIdx = 0;
let lbLista = GALERIA;

function openLB(idx, lista) {
  lbLista = lista || GALERIA;
  lbIdx = idx;
  renderLB();
  document.getElementById('lightbox').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function renderLB() {
  const f = lbLista[lbIdx]; if(!f) return;
  lbReset();
  const img = document.getElementById('lb-img');
  img.classList.remove('ok');
  img.src = f.src;
  if(img.complete && img.naturalWidth) img.classList.add('ok');
  document.getElementById('lb-caption').textContent = f.nombre || f.caption || '';
  document.getElementById('lb-sub').textContent = f.lugar || '';
  document.getElementById('lb-ficha').style.display = f.aveId ? 'inline-block' : 'none';
  document.getElementById('lb-counter').textContent = (lbIdx + 1) + ' / ' + lbLista.length;
  document.getElementById('lb-prev').disabled = lbIdx === 0;
  document.getElementById('lb-next').disabled = lbIdx === lbLista.length - 1;
  const sig = lbLista[lbIdx + 1]; if(sig) { const pre = new Image(); pre.src = sig.src; }  // precarga
}

function lbNav(dir) {
  lbIdx = Math.max(0, Math.min(lbLista.length - 1, lbIdx + dir));
  renderLB();
}

function closeLB() {
  document.getElementById('lightbox').classList.remove('open');
  document.body.style.overflow = '';
}

function lbClickOut(e) {
  if(e.target.id === 'lightbox') closeLB();
}

// ── NAVEGACIÓN MODAL ÁLBUM ────────────────────────────────────────────────────
let avesOrdenadas = [];

function modalNav(dir) {
  // Si venimos del mapa / portada / datos, se usa esa lista; si no, la del álbum con sus filtros
  const lista = mapaAvesOrdenadas.length ? mapaAvesOrdenadas : avesFiltradas();
  const idx = lista.findIndex(a => a.id === curId);
  const newIdx = idx + dir;
  if(newIdx >= 0 && newIdx < lista.length) { modalNavDir = dir; openM(lista[newIdx].id); }
}

function updateModalArrows() {
  const baseNav = mapaAvesOrdenadas.length ? mapaAvesOrdenadas : avesFiltradas();
  const idx = baseNav.findIndex(a => a.id === curId);
  const prevBtn = document.getElementById('m-prev-btn');
  const nextBtn = document.getElementById('m-next-btn');
  if(prevBtn) prevBtn.disabled = idx <= 0;
  if(nextBtn) nextBtn.disabled = idx < 0 || idx >= baseNav.length - 1;
}


// Navegación con teclado
document.addEventListener('keydown', e => {
  if(document.getElementById('lightbox').classList.contains('open')) {
    if(e.key==='ArrowLeft') lbNav(-1);
    else if(e.key==='ArrowRight') lbNav(1);
    else if(e.key==='Escape') closeLB();
  } else if(document.getElementById('modal-ov').classList.contains('open')) {
    if(e.key==='ArrowLeft') modalNav(-1);
    else if(e.key==='ArrowRight') modalNav(1);
    else if(e.key==='Escape') closeM();
  }
});

